interface Todo {
  title: string;
  description: string;
  completed: boolean;
}

// We want a function to update just ONE piece of the Todo
// Using Partial<Todo> means the object can have 1, 2, or all 3 properties
function updateTodo(todoToUpdate: Todo, fieldsToUpdate: Partial<Todo>) {
  return { ...todoToUpdate, ...fieldsToUpdate };
}

const todo1: Todo = { title: "Clean room", description: "Before noon", completed: false };

// We only provide 'completed', which is perfectly valid for Partial<Todo>
const updatedTodo = updateTodo(todo1, {
  completed: true
});
